export function SideNavCollapseButton({
  ref,
  collapsible,
  handleRef,
  label,
  size,
  children,
  onClick: onClickProp,
  ...props
}: SideNavCollapseButtonProps) {
  const t = useComponentTranslator();
  const {isCollapsed, toggle, isCollapsible} = useSideNavCollapseState(
    collapsible,
    handleRef,
