  }

  // --- Arena hooks (internal) ----------------------------------------------

  /** @internal Whether this recognizer takes `touch` right now. */
  protected wantsTouch(touch: GestureTouch): boolean {
    if (this.state !== 'possible' && !isActive(this.state)) {
      return false;
