/** Tell every watcher the reported elements changed; one's throw stops none. */
function notifyWatchers(): void {
  if (presented.batchDepth > 0) {
    presented.isChanged = true;
    return;
  }
  for (const watcher of [...watchers]) {
    try {
      watcher();
    } catch (error) {
      queueMicrotask(() => {
        throw error;
      });
    }
  }
