const UIKIT_LEGACY_OMEGA_DURATION: ReadonlyArray<readonly [number, number]> = [
  [0.1, 46.102],
  [0.15, 33.4801],
  [0.2, 26.5936],
  [0.25, 22.2149],
  [0.3, 19.1698],
  [0.35, 16.9236],
  [0.4, 15.1966],
  [0.45, 13.8275],
